# WAR ARENA - Fix .env loader (last value wins) + show corsOrigin in log - Installer
# Fixes CORS: a stray empty CORS_ORIGIN= line no longer shadows the real value.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-env-fix.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - env loader fix installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/deploy/server.ts" ""
Write-B64 "src/deploy/env.ts" ""

Write-Host ""; Write-Host "Building ..." -ForegroundColor Cyan
npm run build; if ($LASTEXITCODE -ne 0){ throw "build failed" }
Write-Host ""; Write-Host "Fixed + built. Restart: npm start (watch for corsOrigin:http://localhost:8000 in the log)." -ForegroundColor Green
